            new_routes.append(nr)
            if nr != r:
                changed = True
        routes = normalize(new_routes)

        # Beneficial merges
        merged = False
        best_pair = None
        best_key = None
        m = len(routes)
        for i in range(m):
            for j in range(i + 1, m):
                rr = try_merge(routes[i], routes[j])
                if rr is not None:
                    delta = rcost(rr) - rcost(routes[i]) - rcost(routes[j])
                    key = (delta, i, j, tuple(rr))
                    if best_key is None or key < best_key:
                        best_key = key
                        best_pair = (i, j, rr)
        if best_pair is not None and best_key[0] < 0:
            i, j, rr = best_pair
            nroutes = []
            for k in range(len(routes)):
                if k != i and k != j:
                    nroutes.append(routes[k])
            nroutes.append(rr)
            routes = normalize(nroutes)
            changed = True
            merged = True

        if merged:
            continue

        nr = relocate_move(routes)
        if nr is not None:
            routes = nr
            changed = True
            continue

        nr = swap_move(routes)
        if nr is not None:
            routes = nr
            changed = True
            continue

        if not changed:
            break

    # Final cleanup: remove empties and sort.
    routes = normalize(routes)
    return routes
